-- Migrates Firebase-like JSON documents from app_documents to the relational schema.
--
-- Relational primary keys are generated by PostgreSQL identities. Legacy
-- document identifiers are kept in dedicated columns only to make the import
-- replayable and to rebuild parent/child links from the former document store.

create or replace function pg_temp.safe_uuid(value text)
returns uuid
language plpgsql
immutable
as $$
begin
  if value is null or btrim(value) = '' then
    return null;
  end if;

  return value::uuid;
exception
  when invalid_text_representation then
    return null;
end;
$$;

create or replace function pg_temp.safe_timestamptz(value text)
returns timestamptz
language plpgsql
immutable
as $$
begin
  if value is null or btrim(value) = '' then
    return null;
  end if;

  return value::timestamptz;
exception
  when others then
    return null;
end;
$$;

create or replace function pg_temp.safe_time(value text)
returns time
language plpgsql
immutable
as $$
begin
  if value is null or btrim(value) = '' then
    return null;
  end if;

  return value::time;
exception
  when others then
    return null;
end;
$$;

create or replace function pg_temp.safe_boolean(value text)
returns boolean
language sql
immutable
as $$
  select case lower(coalesce(value, ''))
    when 'true' then true
    when 'false' then false
    else false
  end;
$$;

create or replace function pg_temp.user_role_from_document(value text)
returns public.user_role
language sql
immutable
as $$
  select case value
    when '0' then 'admin'::public.user_role
    when '2' then 'initiator'::public.user_role
    when '3' then 'director'::public.user_role
    else 'user'::public.user_role
  end;
$$;

create or replace function pg_temp.schedule_day_from_document(value text)
returns public.schedule_day
language sql
immutable
as $$
  select case lower(coalesce(value, ''))
    when 'lundi' then 'monday'::public.schedule_day
    when 'monday' then 'monday'::public.schedule_day
    when 'mardi' then 'tuesday'::public.schedule_day
    when 'tuesday' then 'tuesday'::public.schedule_day
    when 'mercredi' then 'wednesday'::public.schedule_day
    when 'wednesday' then 'wednesday'::public.schedule_day
    when 'jeudi' then 'thursday'::public.schedule_day
    when 'thursday' then 'thursday'::public.schedule_day
    when 'vendredi' then 'friday'::public.schedule_day
    when 'friday' then 'friday'::public.schedule_day
    when 'samedi' then 'saturday'::public.schedule_day
    when 'saturday' then 'saturday'::public.schedule_day
    when 'dimanche' then 'sunday'::public.schedule_day
    when 'sunday' then 'sunday'::public.schedule_day
    when 'jour férié' then 'public_holiday'::public.schedule_day
    when 'jour ferie' then 'public_holiday'::public.schedule_day
    when 'public_holiday' then 'public_holiday'::public.schedule_day
    else null
  end;
$$;

create or replace function pg_temp.signature_mode_from_document(value text)
returns public.signature_mode
language sql
immutable
as $$
  select case value
    when 'image' then 'image'::public.signature_mode
    when 'draw' then 'draw'::public.signature_mode
    else 'name'::public.signature_mode
  end;
$$;

create or replace function pg_temp.optional_signature_mode_from_document(value text)
returns public.signature_mode
language sql
immutable
as $$
  select case value
    when 'image' then 'image'::public.signature_mode
    when 'draw' then 'draw'::public.signature_mode
    when 'name' then 'name'::public.signature_mode
    else null
  end;
$$;

create or replace function pg_temp.resolve_app_user_id(identifier text)
returns bigint
language sql
stable
as $$
  select app_user.id
  from public.app_users app_user
  where app_user.legacy_document_id = identifier
     or app_user.auth_user_id = pg_temp.safe_uuid(identifier)
     or app_user.email = identifier
  order by
    case
      when app_user.legacy_document_id = identifier then 1
      when app_user.auth_user_id = pg_temp.safe_uuid(identifier) then 2
      else 3
    end
  limit 1;
$$;

create or replace function pg_temp.document_visa_signed_at(visa jsonb)
returns timestamptz
language sql
immutable
as $$
  select case
    when pg_temp.safe_boolean(visa ->> 'signed') then pg_temp.safe_timestamptz(visa ->> 'signedAt')
    else null
  end;
$$;

create or replace function pg_temp.document_visa_signed_name(visa jsonb)
returns text
language sql
immutable
as $$
  select case
    when pg_temp.safe_boolean(visa ->> 'signed') then coalesce(nullif(visa ->> 'signedByName', ''), 'Signature migrée')
    else ''
  end;
$$;

create or replace function pg_temp.document_visa_signed_by_user_id(visa jsonb)
returns bigint
language sql
stable
as $$
  select case
    when pg_temp.safe_boolean(visa ->> 'signed') then pg_temp.resolve_app_user_id(visa ->> 'signedByUid')
    else null
  end;
$$;

create or replace function pg_temp.document_visa_signature_value(visa jsonb)
returns text
language sql
immutable
as $$
  select case
    when pg_temp.safe_boolean(visa ->> 'signed') then coalesce(visa ->> 'signatureValue', '')
    else ''
  end;
$$;

insert into public.app_users (
  auth_user_id,
  legacy_document_id,
  email,
  display_name,
  role,
  signature_mode,
  signature_name,
  signature_image,
  signature_drawing,
  last_login_at,
  created_at,
  updated_at
)
select
  auth_user.id,
  document.document_id,
  coalesce(nullif(document.data ->> 'email', ''), auth_user.email, ''),
  coalesce(document.data ->> 'displayName', ''),
  pg_temp.user_role_from_document(document.data ->> 'role'),
  pg_temp.signature_mode_from_document(document.data ->> 'signatureMode'),
  coalesce(document.data ->> 'signatureName', ''),
  coalesce(document.data ->> 'signatureImage', ''),
  coalesce(document.data ->> 'signatureDrawing', ''),
  pg_temp.safe_timestamptz(document.data ->> 'lastLoginAt'),
  document.created_at,
  document.updated_at
from public.app_documents document
join auth.users auth_user
  on auth_user.id = coalesce(pg_temp.safe_uuid(document.data ->> 'uid'), pg_temp.safe_uuid(document.document_id))
where document.collection_name = 'settings.users'
on conflict (auth_user_id) do update set
  legacy_document_id = excluded.legacy_document_id,
  email = excluded.email,
  display_name = excluded.display_name,
  role = excluded.role,
  signature_mode = excluded.signature_mode,
  signature_name = excluded.signature_name,
  signature_image = excluded.signature_image,
  signature_drawing = excluded.signature_drawing,
  last_login_at = excluded.last_login_at,
  updated_at = excluded.updated_at;

insert into public.teams (legacy_document_id, name, created_at, updated_at)
select
  document.document_id,
  coalesce(nullif(document.data ->> 'name', ''), 'Equipe migrée'),
  document.created_at,
  document.updated_at
from public.app_documents document
where document.collection_name = 'settings.teams'
on conflict (legacy_document_id) do update set
  name = excluded.name,
  updated_at = excluded.updated_at;

insert into public.team_members (team_id, user_id, created_at)
select distinct
  team.id,
  resolved_user.id,
  document.created_at
from public.app_documents document
join public.teams team
  on team.legacy_document_id = document.document_id
cross join lateral jsonb_array_elements(coalesce(document.data -> 'members', '[]'::jsonb)) with ordinality member(value, index)
join lateral (
  select pg_temp.resolve_app_user_id(
    case
      when jsonb_typeof(member.value) = 'string' then trim(both '"' from member.value::text)
      when jsonb_typeof(member.value) = 'object' then coalesce(member.value ->> 'id', member.value ->> 'uid', member.value ->> 'email')
      else null
    end
  ) as id
) resolved_user on resolved_user.id is not null
where document.collection_name = 'settings.teams'
on conflict (team_id, user_id) do nothing;

insert into public.schedule_rules (legacy_document_id, day, hour_start, hour_end, created_at, updated_at)
select
  document.document_id,
  pg_temp.schedule_day_from_document(document.data ->> 'day'),
  pg_temp.safe_time(document.data ->> 'hoStart'),
  pg_temp.safe_time(document.data ->> 'hoEnd'),
  document.created_at,
  document.updated_at
from public.app_documents document
where document.collection_name = 'settings.scheduleRules'
  and pg_temp.schedule_day_from_document(document.data ->> 'day') is not null
  and pg_temp.safe_time(document.data ->> 'hoStart') is not null
  and pg_temp.safe_time(document.data ->> 'hoEnd') is not null
  and pg_temp.safe_time(document.data ->> 'hoStart') < pg_temp.safe_time(document.data ->> 'hoEnd')
on conflict (legacy_document_id) do update set
  day = excluded.day,
  hour_start = excluded.hour_start,
  hour_end = excluded.hour_end,
  updated_at = excluded.updated_at;

insert into public.public_holidays (legacy_document_id, zone, holiday_date, label, source, created_at, updated_at)
select
  document.document_id,
  coalesce(nullif(document.data ->> 'zone', ''), 'metropole'),
  (document.data ->> 'date')::date,
  coalesce(nullif(document.data ->> 'label', ''), 'Jour férié'),
  case when document.data ->> 'source' = 'manual' then 'manual'::public.public_holiday_source else 'api.gouv.fr'::public.public_holiday_source end,
  document.created_at,
  document.updated_at
from public.app_documents document
where document.collection_name = 'settings.publicHolidays'
  and pg_temp.safe_timestamptz(document.data ->> 'date') is not null
on conflict (zone, holiday_date) do update set
  legacy_document_id = excluded.legacy_document_id,
  label = excluded.label,
  source = excluded.source,
  updated_at = excluded.updated_at;

insert into public.rh_on_call_compensation_rules (code, label, coefficient, sort_order, updated_at)
select
  row_data.value ->> 'id',
  coalesce(nullif(row_data.value ->> 'label', ''), row_data.value ->> 'id'),
  coalesce((row_data.value ->> 'coefficient')::numeric, 0),
  row_data.index::integer,
  document.updated_at
from public.app_documents document
cross join lateral jsonb_array_elements(coalesce(document.data -> 'onCall', '[]'::jsonb)) with ordinality row_data(value, index)
where document.collection_name = 'settings'
  and document.document_id = 'rhCompensationRules'
  and row_data.value ? 'id'
on conflict (code) do update set
  label = excluded.label,
  coefficient = excluded.coefficient,
  sort_order = excluded.sort_order,
  updated_at = excluded.updated_at;

insert into public.rh_period_compensation_rules (
  code,
  label,
  intervention_coefficient,
  work_coefficient,
  rest_coefficient,
  sort_order,
  updated_at
)
select
  row_data.value ->> 'id',
  coalesce(nullif(row_data.value ->> 'label', ''), row_data.value ->> 'id'),
  coalesce((row_data.value ->> 'interventionCoefficient')::numeric, 0),
  coalesce((row_data.value ->> 'workCoefficient')::numeric, 0),
  coalesce((row_data.value ->> 'restCoefficient')::numeric, 0),
  row_data.index::integer,
  document.updated_at
from public.app_documents document
cross join lateral jsonb_array_elements(coalesce(document.data -> 'periods', '[]'::jsonb)) with ordinality row_data(value, index)
where document.collection_name = 'settings'
  and document.document_id = 'rhCompensationRules'
  and row_data.value ? 'id'
on conflict (code) do update set
  label = excluded.label,
  intervention_coefficient = excluded.intervention_coefficient,
  work_coefficient = excluded.work_coefficient,
  rest_coefficient = excluded.rest_coefficient,
  sort_order = excluded.sort_order,
  updated_at = excluded.updated_at;

insert into public.rh_export_settings (singleton_key, generation_api_url, updated_at)
select
  true,
  coalesce(nullif(document.data ->> 'generationApiUrl', ''), 'http://localhost:3000/v1/documents/generate'),
  document.updated_at
from public.app_documents document
where document.collection_name = 'settings'
  and document.document_id = 'rhExportTemplates'
on conflict (singleton_key) do update set
  generation_api_url = excluded.generation_api_url,
  updated_at = excluded.updated_at;

insert into public.rh_export_templates (
  code,
  label,
  file_name,
  template_file_name,
  data_model_file_name,
  generation_template,
  data_model,
  updated_at
)
select
  document.document_id,
  coalesce(nullif(document.data ->> 'label', ''), document.document_id),
  coalesce(document.data ->> 'fileName', ''),
  coalesce(document.data ->> 'templateFileName', ''),
  coalesce(document.data ->> 'dataModelFileName', ''),
  document.data -> 'generationTemplate',
  document.data -> 'dataModel',
  document.updated_at
from public.app_documents document
where document.collection_name = 'settings.rhExportTemplates'
on conflict (code) do update set
  label = excluded.label,
  file_name = excluded.file_name,
  template_file_name = excluded.template_file_name,
  data_model_file_name = excluded.data_model_file_name,
  generation_template = excluded.generation_template,
  data_model = excluded.data_model,
  updated_at = excluded.updated_at;

insert into public.regular_on_call_periods (
  legacy_document_id,
  team_id,
  user_id,
  starts_at,
  ends_at,
  sent_to_rh_at,
  created_at,
  updated_at
)
select
  document.document_id,
  team.id,
  resolved_user.id,
  pg_temp.safe_timestamptz(document.data ->> 'startDate'),
  pg_temp.safe_timestamptz(document.data ->> 'endDate'),
  pg_temp.safe_timestamptz(document.data ->> 'sentToRhAt'),
  document.created_at,
  document.updated_at
from public.app_documents document
left join public.teams team
  on team.legacy_document_id = document.data ->> 'teamId'
join lateral (
  select pg_temp.resolve_app_user_id(coalesce(document.data ->> 'userId', document.data ->> 'userEmail')) as id
) resolved_user on resolved_user.id is not null
where document.collection_name = 'regularOnCallPeriods'
  and pg_temp.safe_timestamptz(document.data ->> 'startDate') is not null
  and pg_temp.safe_timestamptz(document.data ->> 'endDate') is not null
  and pg_temp.safe_timestamptz(document.data ->> 'startDate') < pg_temp.safe_timestamptz(document.data ->> 'endDate')
on conflict (legacy_document_id) do update set
  team_id = excluded.team_id,
  user_id = excluded.user_id,
  starts_at = excluded.starts_at,
  ends_at = excluded.ends_at,
  sent_to_rh_at = excluded.sent_to_rh_at,
  updated_at = excluded.updated_at;

insert into public.regular_interventions (
  legacy_document_id,
  regular_period_id,
  user_id,
  starts_at,
  ends_at,
  comment,
  created_at,
  updated_at
)
select
  coalesce(document.parent_id, '') || ':' || document.document_id,
  parent_period.id,
  resolved_user.id,
  pg_temp.safe_timestamptz(document.data ->> 'startDate'),
  pg_temp.safe_timestamptz(document.data ->> 'endDate'),
  coalesce(document.data ->> 'comment', ''),
  document.created_at,
  document.updated_at
from public.app_documents document
join public.regular_on_call_periods parent_period
  on parent_period.legacy_document_id = coalesce(document.parent_id, document.data ->> 'periodId')
join lateral (
  select pg_temp.resolve_app_user_id(coalesce(document.data ->> 'userId', document.data ->> 'userEmail')) as id
) resolved_user on resolved_user.id is not null
where document.collection_name = 'regularInterventions'
  and pg_temp.safe_timestamptz(document.data ->> 'startDate') is not null
  and pg_temp.safe_timestamptz(document.data ->> 'endDate') is not null
  and pg_temp.safe_timestamptz(document.data ->> 'startDate') < pg_temp.safe_timestamptz(document.data ->> 'endDate')
  and resolved_user.id = parent_period.user_id
  and pg_temp.safe_timestamptz(document.data ->> 'startDate') >= parent_period.starts_at
  and pg_temp.safe_timestamptz(document.data ->> 'endDate') <= parent_period.ends_at
on conflict (legacy_document_id) do update set
  regular_period_id = excluded.regular_period_id,
  user_id = excluded.user_id,
  starts_at = excluded.starts_at,
  ends_at = excluded.ends_at,
  comment = excluded.comment,
  updated_at = excluded.updated_at;

insert into public.exceptional_operations (
  legacy_document_id,
  operation_type,
  initiator_user_id,
  operation_manager_user_id,
  operation_manager_name,
  title,
  planned_starts_at,
  planned_ends_at,
  actual_starts_at,
  actual_ends_at,
  sent_to_rh_at,
  created_at,
  updated_at
)
select
  document.document_id,
  case when document.data ->> 'type' = 'travaux' then 'extra_work'::public.exceptional_operation_type else 'on_call'::public.exceptional_operation_type end,
  pg_temp.resolve_app_user_id(document.data ->> 'initiatorUid'),
  pg_temp.resolve_app_user_id(document.data ->> 'operationManagerUid'),
  coalesce(document.data ->> 'operationManagerName', ''),
  coalesce(nullif(document.data ->> 'title', ''), 'Opération migrée'),
  pg_temp.safe_timestamptz(document.data ->> 'startDate'),
  pg_temp.safe_timestamptz(document.data ->> 'forecastEndDate'),
  pg_temp.safe_timestamptz(document.data ->> 'actualStartDate'),
  pg_temp.safe_timestamptz(document.data ->> 'actualEndDate'),
  pg_temp.safe_timestamptz(document.data ->> 'sentToRhAt'),
  document.created_at,
  document.updated_at
from public.app_documents document
where document.collection_name = 'exceptionalOperations'
on conflict (legacy_document_id) do update set
  operation_type = excluded.operation_type,
  initiator_user_id = excluded.initiator_user_id,
  operation_manager_user_id = excluded.operation_manager_user_id,
  operation_manager_name = excluded.operation_manager_name,
  title = excluded.title,
  planned_starts_at = excluded.planned_starts_at,
  planned_ends_at = excluded.planned_ends_at,
  actual_starts_at = excluded.actual_starts_at,
  actual_ends_at = excluded.actual_ends_at,
  sent_to_rh_at = excluded.sent_to_rh_at,
  updated_at = excluded.updated_at;

insert into public.exceptional_operation_participants (
  legacy_document_id,
  operation_id,
  participant_kind,
  user_id,
  starts_at,
  ends_at,
  created_at,
  updated_at
)
select
  operation.legacy_document_id || ':' || participant.kind || ':' || participant.index || ':' || resolved_user.id::text,
  operation.id,
  participant.kind::public.operation_participant_kind,
  resolved_user.id,
  pg_temp.safe_timestamptz(participant.value ->> 'startDate'),
  pg_temp.safe_timestamptz(participant.value ->> 'endDate'),
  document.created_at,
  document.updated_at
from public.app_documents document
join public.exceptional_operations operation
  on operation.legacy_document_id = document.document_id
cross join lateral (
  select 'planned' as kind, planned.value, planned.index
  from jsonb_array_elements(coalesce(document.data -> 'plannedUsers', '[]'::jsonb)) with ordinality planned(value, index)
  union all
  select 'actual' as kind, actual.value, actual.index
  from jsonb_array_elements(coalesce(document.data -> 'actualUsers', '[]'::jsonb)) with ordinality actual(value, index)
) participant
join lateral (
  select pg_temp.resolve_app_user_id(coalesce(participant.value ->> 'userId', participant.value ->> 'email')) as id
) resolved_user on resolved_user.id is not null
where document.collection_name = 'exceptionalOperations'
  and pg_temp.safe_timestamptz(participant.value ->> 'startDate') is not null
  and pg_temp.safe_timestamptz(participant.value ->> 'endDate') is not null
  and pg_temp.safe_timestamptz(participant.value ->> 'startDate') < pg_temp.safe_timestamptz(participant.value ->> 'endDate')
on conflict (legacy_document_id) do update set
  operation_id = excluded.operation_id,
  participant_kind = excluded.participant_kind,
  user_id = excluded.user_id,
  starts_at = excluded.starts_at,
  ends_at = excluded.ends_at,
  updated_at = excluded.updated_at;

insert into public.exceptional_interventions (
  legacy_document_id,
  operation_id,
  user_id,
  starts_at,
  ends_at,
  was_on_site,
  label,
  comment,
  created_at,
  updated_at
)
select
  operation.legacy_document_id || ':' || intervention.index || ':' || resolved_user.id::text,
  operation.id,
  resolved_user.id,
  pg_temp.safe_timestamptz(intervention.value ->> 'startDate'),
  pg_temp.safe_timestamptz(intervention.value ->> 'endDate'),
  pg_temp.safe_boolean(intervention.value ->> 'wasOnSite'),
  coalesce(intervention.value ->> 'label', ''),
  coalesce(intervention.value ->> 'comment', ''),
  document.created_at,
  document.updated_at
from public.app_documents document
join public.exceptional_operations operation
  on operation.legacy_document_id = document.document_id
cross join lateral jsonb_array_elements(coalesce(document.data -> 'interventions', '[]'::jsonb)) with ordinality intervention(value, index)
join lateral (
  select pg_temp.resolve_app_user_id(coalesce(intervention.value ->> 'userId', intervention.value ->> 'userEmail')) as id
) resolved_user on resolved_user.id is not null
where document.collection_name = 'exceptionalOperations'
  and pg_temp.safe_timestamptz(intervention.value ->> 'startDate') is not null
  and pg_temp.safe_timestamptz(intervention.value ->> 'endDate') is not null
  and pg_temp.safe_timestamptz(intervention.value ->> 'startDate') < pg_temp.safe_timestamptz(intervention.value ->> 'endDate')
  and exists (
    select 1
    from public.exceptional_operation_participants participant
    where participant.operation_id = operation.id
      and participant.participant_kind = 'actual'
      and participant.user_id = resolved_user.id
      and participant.starts_at <= pg_temp.safe_timestamptz(intervention.value ->> 'startDate')
      and participant.ends_at >= pg_temp.safe_timestamptz(intervention.value ->> 'endDate')
  )
on conflict (legacy_document_id) do update set
  operation_id = excluded.operation_id,
  user_id = excluded.user_id,
  starts_at = excluded.starts_at,
  ends_at = excluded.ends_at,
  was_on_site = excluded.was_on_site,
  label = excluded.label,
  comment = excluded.comment,
  updated_at = excluded.updated_at;

insert into public.visas (
  legacy_document_id,
  scope,
  regular_period_id,
  signed_by_user_id,
  signed_by_name,
  signed_at,
  signature_mode,
  signature_value,
  created_at,
  updated_at
)
select
  'regular-period-agent:' || document.document_id,
  'regular_period_agent'::public.visa_scope,
  regular_period.id,
  pg_temp.document_visa_signed_by_user_id(document.data -> 'agentVisa'),
  pg_temp.document_visa_signed_name(document.data -> 'agentVisa'),
  pg_temp.document_visa_signed_at(document.data -> 'agentVisa'),
  pg_temp.optional_signature_mode_from_document(document.data #>> '{agentVisa,signatureMode}'),
  pg_temp.document_visa_signature_value(document.data -> 'agentVisa'),
  document.created_at,
  document.updated_at
from public.app_documents document
join public.regular_on_call_periods regular_period
  on regular_period.legacy_document_id = document.document_id
where document.collection_name = 'regularOnCallPeriods'
  and document.data -> 'agentVisa' is not null
on conflict (regular_period_id, scope) where regular_period_id is not null do update set
  legacy_document_id = excluded.legacy_document_id,
  signed_by_user_id = excluded.signed_by_user_id,
  signed_by_name = excluded.signed_by_name,
  signed_at = excluded.signed_at,
  signature_mode = excluded.signature_mode,
  signature_value = excluded.signature_value,
  updated_at = excluded.updated_at;

insert into public.visas (
  legacy_document_id,
  scope,
  regular_period_id,
  signed_by_user_id,
  signed_by_name,
  signed_at,
  signature_mode,
  signature_value,
  created_at,
  updated_at
)
select
  'regular-period-director:' || document.document_id,
  'regular_period_director'::public.visa_scope,
  regular_period.id,
  pg_temp.document_visa_signed_by_user_id(document.data -> 'directorVisa'),
  pg_temp.document_visa_signed_name(document.data -> 'directorVisa'),
  pg_temp.document_visa_signed_at(document.data -> 'directorVisa'),
  pg_temp.optional_signature_mode_from_document(document.data #>> '{directorVisa,signatureMode}'),
  pg_temp.document_visa_signature_value(document.data -> 'directorVisa'),
  document.created_at,
  document.updated_at
from public.app_documents document
join public.regular_on_call_periods regular_period
  on regular_period.legacy_document_id = document.document_id
where document.collection_name = 'regularOnCallPeriods'
  and document.data -> 'directorVisa' is not null
on conflict (regular_period_id, scope) where regular_period_id is not null do update set
  legacy_document_id = excluded.legacy_document_id,
  signed_by_user_id = excluded.signed_by_user_id,
  signed_by_name = excluded.signed_by_name,
  signed_at = excluded.signed_at,
  signature_mode = excluded.signature_mode,
  signature_value = excluded.signature_value,
  updated_at = excluded.updated_at;

insert into public.visas (
  legacy_document_id,
  scope,
  regular_intervention_id,
  signed_by_user_id,
  signed_by_name,
  signed_at,
  signature_mode,
  signature_value,
  created_at,
  updated_at
)
select
  'regular-intervention-agent:' || regular_intervention.legacy_document_id,
  'regular_intervention_agent'::public.visa_scope,
  regular_intervention.id,
  pg_temp.document_visa_signed_by_user_id(document.data -> 'agentVisa'),
  pg_temp.document_visa_signed_name(document.data -> 'agentVisa'),
  pg_temp.document_visa_signed_at(document.data -> 'agentVisa'),
  pg_temp.optional_signature_mode_from_document(document.data #>> '{agentVisa,signatureMode}'),
  pg_temp.document_visa_signature_value(document.data -> 'agentVisa'),
  document.created_at,
  document.updated_at
from public.app_documents document
join public.regular_interventions regular_intervention
  on regular_intervention.legacy_document_id = coalesce(document.parent_id, '') || ':' || document.document_id
where document.collection_name = 'regularInterventions'
  and document.data -> 'agentVisa' is not null
on conflict (regular_intervention_id, scope) where regular_intervention_id is not null do update set
  legacy_document_id = excluded.legacy_document_id,
  signed_by_user_id = excluded.signed_by_user_id,
  signed_by_name = excluded.signed_by_name,
  signed_at = excluded.signed_at,
  signature_mode = excluded.signature_mode,
  signature_value = excluded.signature_value,
  updated_at = excluded.updated_at;

insert into public.visas (
  legacy_document_id,
  scope,
  exceptional_operation_id,
  signed_by_user_id,
  signed_by_name,
  signed_at,
  signature_mode,
  signature_value,
  created_at,
  updated_at
)
select
  visa_item.scope::text || ':' || operation.legacy_document_id,
  visa_item.scope::public.visa_scope,
  operation.id,
  pg_temp.document_visa_signed_by_user_id(visa_item.visa),
  pg_temp.document_visa_signed_name(visa_item.visa),
  pg_temp.document_visa_signed_at(visa_item.visa),
  pg_temp.optional_signature_mode_from_document(visa_item.visa ->> 'signatureMode'),
  pg_temp.document_visa_signature_value(visa_item.visa),
  document.created_at,
  document.updated_at
from public.app_documents document
join public.exceptional_operations operation
  on operation.legacy_document_id = document.document_id
cross join lateral (
  values
    ('exceptional_operation_initiator', document.data #> '{visas,initiatorGlobal}'),
    ('exceptional_operation_director', document.data #> '{visas,directorGlobal}'),
    ('exceptional_planned_initiator', document.data #> '{visas,plannedInitiator}'),
    ('exceptional_planned_director', document.data #> '{visas,plannedDirector}'),
    ('exceptional_actual_initiator', document.data #> '{visas,actualInitiator}'),
    ('exceptional_actual_director', document.data #> '{visas,actualDirector}')
) visa_item(scope, visa)
where document.collection_name = 'exceptionalOperations'
  and visa_item.visa is not null
on conflict (exceptional_operation_id, scope) where exceptional_operation_id is not null do update set
  legacy_document_id = excluded.legacy_document_id,
  signed_by_user_id = excluded.signed_by_user_id,
  signed_by_name = excluded.signed_by_name,
  signed_at = excluded.signed_at,
  signature_mode = excluded.signature_mode,
  signature_value = excluded.signature_value,
  updated_at = excluded.updated_at;

insert into public.visas (
  legacy_document_id,
  scope,
  exceptional_participant_id,
  signed_by_user_id,
  signed_by_name,
  signed_at,
  signature_mode,
  signature_value,
  created_at,
  updated_at
)
select
  'exceptional-participant-agent:' || persisted_participant.legacy_document_id,
  'exceptional_participant_agent'::public.visa_scope,
  persisted_participant.id,
  pg_temp.document_visa_signed_by_user_id(participant.value -> 'visa'),
  pg_temp.document_visa_signed_name(participant.value -> 'visa'),
  pg_temp.document_visa_signed_at(participant.value -> 'visa'),
  pg_temp.optional_signature_mode_from_document(participant.value -> 'visa' ->> 'signatureMode'),
  pg_temp.document_visa_signature_value(participant.value -> 'visa'),
  document.created_at,
  document.updated_at
from public.app_documents document
join public.exceptional_operations operation
  on operation.legacy_document_id = document.document_id
cross join lateral (
  select 'planned' as kind, planned.value, planned.index
  from jsonb_array_elements(coalesce(document.data -> 'plannedUsers', '[]'::jsonb)) with ordinality planned(value, index)
  union all
  select 'actual' as kind, actual.value, actual.index
  from jsonb_array_elements(coalesce(document.data -> 'actualUsers', '[]'::jsonb)) with ordinality actual(value, index)
) participant
join lateral (
  select pg_temp.resolve_app_user_id(coalesce(participant.value ->> 'userId', participant.value ->> 'email')) as id
) resolved_user on resolved_user.id is not null
join public.exceptional_operation_participants persisted_participant
  on persisted_participant.legacy_document_id = operation.legacy_document_id || ':' || participant.kind || ':' || participant.index || ':' || resolved_user.id::text
where document.collection_name = 'exceptionalOperations'
  and participant.value -> 'visa' is not null
on conflict (exceptional_participant_id, scope) where exceptional_participant_id is not null do update set
  legacy_document_id = excluded.legacy_document_id,
  signed_by_user_id = excluded.signed_by_user_id,
  signed_by_name = excluded.signed_by_name,
  signed_at = excluded.signed_at,
  signature_mode = excluded.signature_mode,
  signature_value = excluded.signature_value,
  updated_at = excluded.updated_at;

insert into public.visas (
  legacy_document_id,
  scope,
  exceptional_intervention_id,
  signed_by_user_id,
  signed_by_name,
  signed_at,
  signature_mode,
  signature_value,
  created_at,
  updated_at
)
select
  'exceptional-intervention-agent:' || persisted_intervention.legacy_document_id,
  'exceptional_intervention_agent'::public.visa_scope,
  persisted_intervention.id,
  pg_temp.document_visa_signed_by_user_id(intervention.value -> 'agentVisa'),
  pg_temp.document_visa_signed_name(intervention.value -> 'agentVisa'),
  pg_temp.document_visa_signed_at(intervention.value -> 'agentVisa'),
  pg_temp.optional_signature_mode_from_document(intervention.value -> 'agentVisa' ->> 'signatureMode'),
  pg_temp.document_visa_signature_value(intervention.value -> 'agentVisa'),
  document.created_at,
  document.updated_at
from public.app_documents document
join public.exceptional_operations operation
  on operation.legacy_document_id = document.document_id
cross join lateral jsonb_array_elements(coalesce(document.data -> 'interventions', '[]'::jsonb)) with ordinality intervention(value, index)
join lateral (
  select pg_temp.resolve_app_user_id(coalesce(intervention.value ->> 'userId', intervention.value ->> 'userEmail')) as id
) resolved_user on resolved_user.id is not null
join public.exceptional_interventions persisted_intervention
  on persisted_intervention.legacy_document_id = operation.legacy_document_id || ':' || intervention.index || ':' || resolved_user.id::text
where document.collection_name = 'exceptionalOperations'
  and intervention.value -> 'agentVisa' is not null
on conflict (exceptional_intervention_id, scope) where exceptional_intervention_id is not null do update set
  legacy_document_id = excluded.legacy_document_id,
  signed_by_user_id = excluded.signed_by_user_id,
  signed_by_name = excluded.signed_by_name,
  signed_at = excluded.signed_at,
  signature_mode = excluded.signature_mode,
  signature_value = excluded.signature_value,
  updated_at = excluded.updated_at;

-- The legacy ids are only a migration scaffold: they let the script rebuild
-- joins from app_documents while the import is running. Once every target row
-- and visa has been inserted, keeping them would expose the old document model
-- as an accidental long-term contract, so the final step removes them.
alter table public.visas drop column if exists legacy_document_id;
alter table public.exceptional_interventions drop column if exists legacy_document_id;
alter table public.exceptional_operation_participants drop column if exists legacy_document_id;
alter table public.exceptional_operations drop column if exists legacy_document_id;
alter table public.regular_interventions drop column if exists legacy_document_id;
alter table public.regular_on_call_periods drop column if exists legacy_document_id;
alter table public.public_holidays drop column if exists legacy_document_id;
alter table public.schedule_rules drop column if exists legacy_document_id;
alter table public.teams drop column if exists legacy_document_id;
alter table public.app_users drop column if exists legacy_document_id;
